import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DATE_FORM = /^\d{4}-\d{2}-\d{2}$/;

function isId(v: unknown): boolean {
  return (typeof v === 'number' || typeof v === 'string') && /^\d+$/.test(String(v));
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

@Controller('api/v1')
export class FnSfr00702Controller {
  @Post('/tax-invoices/collect')
  @HttpCode(200)
  async collectTaxInvoices(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const fromDate = data['fromDate'];
    const toDate = data['toDate'];
    if (typeof fromDate !== 'string' || !DATE_FORM.test(fromDate)) {
      throw invalid('수집 시작일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    if (typeof toDate !== 'string' || !DATE_FORM.test(toDate)) {
      throw invalid('수집 종료일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    return transaction(async (db) => {
      const ranges = await db.query(
        'SELECT (CAST(:fromDate AS date) <= CAST(:toDate AS date)) AS "ok"',
        { fromDate, toDate },
      );
      if (!ranges[0] || ranges[0]['ok'] !== true) {
        throw invalid('수집 시작일은 종료일보다 늦을 수 없습니다.');
      }
      // 가정: 홈택스 연계 모듈이 수신한 내역은 tax_invoice에 반영되어 있고, 기간 안의 건수를 수집 건수로 센다.
      const rows = await db.query(
        'SELECT COUNT(*) AS "collectedCount" FROM tax_invoice WHERE issue_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date)',
        { fromDate, toDate },
      );
      return { collectedCount: Number(rows[0]['collectedCount']) };
    });
  }

  @Post('/tax-invoices/:taxInvoiceId/create-resolution')
  @HttpCode(200)
  async createTaxInvoiceResolution(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const taxInvoiceId = req.params['taxInvoiceId'];
    if (!isId(taxInvoiceId)) {
      throw invalid('전자세금계산서 ID가 올바르지 않습니다.');
    }
    const taxType = data['taxType'];
    if (taxType !== '과세' && taxType !== '면세') {
      throw invalid('과세·면세 구분을 선택하세요.');
    }
    const resolutionType = data['resolutionType'];
    if (resolutionType !== '지출' && resolutionType !== '수입') {
      throw invalid('결의 유형을 선택하세요.');
    }
    const resolutionDate = data['resolutionDate'];
    if (typeof resolutionDate !== 'string' || !DATE_FORM.test(resolutionDate)) {
      throw invalid('결의일자를 YYYY-MM-DD 형식으로 입력하세요.');
    }
    if (!isId(data['partnerId'])) {
      throw invalid('거래처를 선택하세요.');
    }
    if (!isId(data['departmentId'])) {
      throw invalid('결의부서를 선택하세요.');
    }
    if (!isId(data['projectId'])) {
      throw invalid('프로젝트를 선택하세요.');
    }
    if (!isId(data['budgetItemId'])) {
      throw invalid('예산과목을 선택하세요.');
    }
    const params = {
      taxInvoiceId: String(taxInvoiceId),
      taxType,
      resolutionType,
      resolutionDate,
      partnerId: String(data['partnerId']),
      departmentId: String(data['departmentId']),
      projectId: String(data['projectId']),
      budgetItemId: String(data['budgetItemId']),
      userId: user.id,
    };
    return transaction(async (db) => {
      const invoices = await db.query(
        'SELECT expense_resolution_id AS "expenseResolutionId", reconciliation_result AS "reconciliationResult", supply_amount + tax_amount AS "amount" FROM tax_invoice WHERE tax_invoice_id = CAST(:taxInvoiceId AS bigint) FOR UPDATE',
        { taxInvoiceId: params.taxInvoiceId },
      );
      if (invoices.length === 0) {
        throw new ApiError(404, 'TAX_INVOICE_NOT_FOUND', '전자세금계산서를 찾을 수 없습니다.');
      }
      const invoice = invoices[0];
      if (invoice['expenseResolutionId'] !== null && invoice['expenseResolutionId'] !== undefined) {
        throw new ApiError(409, 'TAX_INVOICE_RESOLUTION_DUPLICATED', '이미 결의서가 작성된 전자세금계산서입니다.');
      }
      if (invoice['reconciliationResult'] !== '일치') {
        throw new ApiError(422, 'TAX_INVOICE_RECONCILIATION_MISMATCH', '대사 결과가 일치인 전자세금계산서만 결의서를 작성할 수 있습니다.');
      }
      if (!(Number(invoice['amount']) > 0)) {
        throw invalid('결의 금액이 0보다 커야 합니다.');
      }
      const refs: [string, string, string, string][] = [
        ['partner', 'partner_id', params.partnerId, '거래처'],
        ['department', 'department_id', params.departmentId, '결의부서'],
        ['project', 'project_id', params.projectId, '프로젝트'],
        ['budget_item', 'budget_item_id', params.budgetItemId, '예산과목'],
      ];
      for (const [table, column, value, label] of refs) {
        const found = await db.query(
          'SELECT 1 AS "ok" FROM ' + table + ' WHERE ' + column + ' = CAST(:value AS bigint)',
          { value },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', label + '을(를) 찾을 수 없습니다.');
        }
      }
      const created = await db.query(
        'INSERT INTO expense_resolution (resolution_date, department_id, author_id, resolution_type, project_id, budget_item_id, partner_id, amount, evidence_type, approval_status, created_at, updated_at) VALUES (CAST(:resolutionDate AS date), CAST(:departmentId AS bigint), CAST(:userId AS bigint), :resolutionType, CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:partnerId AS bigint), (SELECT supply_amount + tax_amount FROM tax_invoice WHERE tax_invoice_id = CAST(:taxInvoiceId AS bigint)), \'전자세금계산서\', \'기안\', now(), now()) RETURNING expense_resolution_id AS "expenseResolutionId"',
        params,
      );
      const expenseResolutionId = Number(created[0]['expenseResolutionId']);
      // 가정: 문서번호는 결의서 ID로 자동 부여한다.
      await db.execute(
        'UPDATE expense_resolution SET document_no = \'ER-\' || lpad(CAST(expense_resolution_id AS text), 8, \'0\'), updated_at = now() WHERE expense_resolution_id = CAST(:id AS bigint)',
        { id: String(expenseResolutionId) },
      );
      await db.execute(
        'UPDATE tax_invoice SET expense_resolution_id = CAST(:id AS bigint), tax_type = :taxType, updated_at = now() WHERE tax_invoice_id = CAST(:taxInvoiceId AS bigint)',
        { id: String(expenseResolutionId), taxType: params.taxType, taxInvoiceId: params.taxInvoiceId },
      );
      return { expenseResolutionId };
    });
  }
}

