import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr00702Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [collecting, setCollecting] = useState(false);
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [lastCount, setLastCount] = useState<number | string>('-');
  const [target, setTarget] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>({ resolutionType: '지출' });

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/tax-invoices', role, undefined, { ...applied, page, size: 20 }),
    [role, page, applied],
  );

  function search() {
    setPage(0);
    setApplied({ startDate, endDate, partnerId });
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setPartnerId('');
    setPage(0);
    setApplied({});
  }

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function openResolution(row: Row) {
    setForm({
      resolutionType: '지출',
      taxType: row['taxType'],
      partnerId: row['partnerId'],
    });
    setTarget(row);
  }

  async function collect() {
    if (!fromDate || !toDate) {
      throw new Error('수집 시작일과 종료일을 입력하세요.');
    }
    const result = await call('POST', '/tax-invoices/collect', role, { fromDate, toDate });
    setLastCount(Number(result['collectedCount']));
    notify('전자세금계산서를 수집했습니다.');
    setCollecting(false);
    reload();
  }

  async function createResolution() {
    if (!target) {
      return;
    }
    const required: [string, string][] = [
      ['taxType', '과세·면세 구분'],
      ['partnerId', '거래처'],
      ['resolutionDate', '결의일자'],
      ['departmentId', '결의부서'],
      ['projectId', '프로젝트'],
      ['budgetItemId', '예산과목'],
      ['resolutionType', '결의 유형'],
    ];
    for (const [key, label] of required) {
      if (form[key] === undefined || form[key] === null || form[key] === '') {
        throw new Error(label + '을(를) 입력하세요.');
      }
    }
    const path = '/tax-invoices/' + String(target['taxInvoiceId']) + '/create-resolution';
    await call('POST', path, role, form);
    notify('결의서를 작성했습니다.');
    setTarget(null);
    reload();
  }

  const rows = data ? data.items : [];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Tiles items={[['전자세금계산서', <Num value={data ? data.total : 0} />]]} />
      </section>
      <section className="box span-4">
        <h2>최근 수집</h2>
        <Tiles items={[['수집 건수', <Num value={lastCount} />]]} />
      </section>
      <section className="box span-12">
        <h2>전자세금계산서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="발행일 시작">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="발행일 종료">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="거래처 ID">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setCollecting(true)}>
            홈택스 수집
          </button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty="전자세금계산서가 없습니다."
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            {
              key: 'partnerId',
              label: '거래처 ID',
              render: (r) => <RefName table="partner" role={role} value={r['partnerId']} />,
            },
            { key: 'direction', label: '매출/매입 구분', render: (r) => <Badge value={r['direction']} /> },
            { key: 'taxType', label: '과세·면세 구분', render: (r) => <Badge value={r['taxType']} /> },
            { key: 'issueDate', label: '작성일자', render: (r) => <DateText value={r['issueDate']} /> },
            { key: 'supplyAmount', label: '공급가액', render: (r) => <Num value={r['supplyAmount']} /> },
            { key: 'taxAmount', label: '세액', render: (r) => <Num value={r['taxAmount']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (
                <button type="button" onClick={() => openResolution(r)}>
                  결의서 작성
                </button>
              ),
            },
          ]}
        />
        <Pager page={page} size={20} total={data ? data.total : 0} onPage={setPage} />
      </section>

      {collecting ? (
        <Drawer title="홈택스 전자세금계산서 수집" onClose={() => setCollecting(false)}>
          <Form onSubmit={collect} submit="수집">
            <Field label="수집 시작일" required>
              <DateInput value={fromDate} onChange={setFromDate} />
            </Field>
            <Field label="수집 종료일" required>
              <DateInput value={toDate} onChange={setToDate} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {target ? (
        <Drawer title="전자세금계산서 결의서 작성" onClose={() => setTarget(null)}>
          <Form onSubmit={createResolution} submit="결의서 작성">
            <Field label="과세·면세 구분" required>
              <Select
                value={form['taxType']}
                onChange={(v) => setField('taxType', v)}
                options={[['과세', '과세'], ['면세', '면세']]}
              />
            </Field>
            <Field label="거래처" required>
              <LookupSelect
                table="partner"
                role={role}
                value={form['partnerId']}
                onChange={(v) => setField('partnerId', v)}
              />
            </Field>
            <Field label="결의일자" required>
              <DateInput value={form['resolutionDate']} onChange={(v) => setField('resolutionDate', v)} />
            </Field>
            <Field label="결의부서" required>
              <LookupSelect
                table="department"
                role={role}
                value={form['departmentId']}
                onChange={(v) => setField('departmentId', v)}
              />
            </Field>
            <Field label="프로젝트" required>
              <LookupSelect
                table="project"
                role={role}
                value={form['projectId']}
                onChange={(v) => setField('projectId', v)}
              />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect
                table="budget_item"
                role={role}
                value={form['budgetItemId']}
                onChange={(v) => setField('budgetItemId', v)}
              />
            </Field>
            <Field label="결의 유형" required>
              <Select
                value={form['resolutionType']}
                onChange={(v) => setField('resolutionType', v)}
                options={[['지출', '지출'], ['수입', '수입']]}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
